          <div class="list-container">
            <template v-if="pendingApprovals.length > 0">
              <div v-for="app in pendingApprovals" :key="app.id" class="list-item" @click="$router.push('/approvals')">
                <el-avatar :size="36" class="avatar">{{ (isApprover ? (app.applicant_name || '无') : (app.approver_name || '无')).charAt(0) }}</el-avatar>
                <div class="item-content">
