                  <div class="item-desc">
                    <el-tag size="small" :type="getStatusTagType(app.status)" class="mr-8">
                      {{ getStatusLabel(app.status) }}
                    </el-tag>
                    {{ isApprover ? '来自 ' + app.applicant_name : '审批人: ' + app.approver_name }}
                  </div>
                </div>
              </div>
            </template>
            <div v-else class="empty-placeholder">
              <el-icon :size="40" color="#c0c4cc"><DocumentChecked /></el-icon>
              <p>{{ isApprover ? '暂无待审批项' : '暂无申请中项目' }}</p>
            </div>
