              <div v-for="msg in recentMessages" :key="msg.id" class="list-item" @click="$router.push('/messages')">
                <div class="item-content">
                  <div class="item-title" :class="{ unread: !msg.is_read }">{{ msg.title }}</div>
                  <div class="item-desc">{{ msg.content }}</div>
                </div>
                <span class="item-time">{{ formatTime(msg.created_at) }}</span>
              </div>
            </template>
