<script setup>
import { ref, onMounted, computed, onUnmounted } from 'vue'
import { 
  Grid, ChatDotRound, Checked, CircleCheck, 
  Monitor, FolderOpened, Calendar, Tools, 
  Collection, Tickets, Setting, Menu, Close,
  Clock, ArrowRight, DocumentChecked, Bell
} from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'
import 'dayjs/locale/zh-cn'
import { ElMessage, ElMessageBox } from 'element-plus'
import EquipmentStatusChart from '@/components/charts/EquipmentStatusChart.vue'
import PopularCategoryChart from '@/components/charts/PopularCategoryChart.vue'

dayjs.locale('zh-cn')

const currentUser = ref(null)
const loading = ref(false)
const myTasks = ref([])
const pendingApprovals = ref([])
const recentMessages = ref([])
const totalEquipments = ref(0)
const activeBorrows = ref(0)

const statusData = ref([])
const categoryData = ref([])

const today = computed(() => dayjs().format('YYYY年MM月DD日'))
const weekDay = computed(() => dayjs().format('dddd'))

const isApprover = computed(() => currentUser.value?.permissions?.includes('approve'))
const canManageBusiness = computed(() => currentUser.value?.permissions?.includes('config_business'))

const pendingApprovalsCount = ref(0)
const unreadMessagesCount = ref(0)

const handleMessageUpdated = async () => {
  try {
    const uid = currentUser.value?.id
    if (!uid) return
    const msgRes = await api.getMessages(uid)
    const msgData = msgRes.data.results || msgRes.data || []
    unreadMessagesCount.value = msgData.filter((m) => !m.is_read).length
  } catch (error) {
    console.error('更新消息统计失败', error)
  }
}

const quickStats = computed(() => [
  { label: '在库设备', value: totalEquipments.value },
  { label: '我的待办', value: myTasks.value.length },
  { label: isApprover.value ? '待我审批' : '我的申请', value: pendingApprovalsCount.value },
  { label: '消息通知', value: unreadMessagesCount.value }
])

const apps = ref([])

const fetchApps = async () => {
  try {
    const res = await api.getLowCodeApps()
    apps.value = res.data.map(app => ({
      id: app.id,
      name: app.name,
      icon: app.icon || 'Menu',
      path: `/lowcode/${app.code}`,
      color: app.color || '#909399'
    }))
  } catch (error) {
    console.error('Failed to fetch apps:', error)
  }
}

const handleDeleteApp = async (app) => {
  try {
    await ElMessageBox.confirm(
      `确定删除业务「${app.name}」吗？仅当该业务下没有任何申请记录时才能删除；若有历史数据，请先到业务配置中停用或清理后再试。`,
      '删除业务',
      {
        confirmButtonText: '确定删除',
        cancelButtonText: '取消',
        type: 'warning'
      }
    )
    
    await api.deleteLowCodeApp(app.id)
    ElMessage.success('删除成功')
    await fetchApps()
  } catch (error) {
    if (error !== 'cancel') {
      console.error('Failed to delete app:', error)
      ElMessage.error(api.getErrorMessage(error, '删除失败'))
    }
  }
}

const fetchData = async () => {
  loading.value = true
  try {
    const profileId = currentUser.value?.id
    
    let params = {}
    if (isApprover.value) {
      params.status = 'pending'
      params.approver = profileId
    } else {
      params.status__in = 'pending,approved' 
      params.applicant = profileId
    }

    let equipRes, taskRes, approvalRes, msgRes, statsRes
    try {
      equipRes = await api.getEquipments()
    } catch(e) { console.error('[设备列表]失败', e); throw new Error('[设备列表] /api/equipments/ 失败: ' + (e?.message || '')) }
    try {
      taskRes = await api.getTasks({ assignee: profileId, status: 'pending,in_progress' })
    } catch(e) { console.error('[任务列表]失败', e); throw new Error('[任务列表] /api/core/tasks/ 失败: ' + (e?.message || '')) }
    try {
      approvalRes = await api.getApprovals(params)
    } catch(e) { console.error('[审批列表]失败', e); throw new Error('[审批列表] /api/core/approvals/ 失败: ' + (e?.message || '')) }
    try {
      msgRes = await api.getMessages(profileId)
    } catch(e) { console.error('[消息列表]失败', e); throw new Error('[消息列表] /api/core/messages/ 失败: ' + (e?.message || '')) }
    try {
      statsRes = await api.getEquipmentStats()
    } catch(e) { console.error('[设备统计]失败', e); throw new Error('[设备统计] /api/equipments/stats/ 失败: ' + (e?.message || '')) }

    totalEquipments.value = (equipRes.data.results || equipRes.data || []).length
    myTasks.value = (taskRes.data.results || taskRes.data || []).filter(t => t.status !== 'completed').slice(0, 5)
    
    const approvalData = approvalRes.data.results || approvalRes.data || []
    pendingApprovals.value = approvalData.slice(0, 5)
    pendingApprovalsCount.value = approvalRes.data.count || approvalData.length
    
    const msgData = msgRes.data.results || msgRes.data || []
    recentMessages.value = msgData.slice(0, 5)
    unreadMessagesCount.value = msgData.filter((m) => !m.is_read).length
    
    if (statsRes.data) {
      statusData.value = statsRes.data.status_distribution || []
      categoryData.value = statsRes.data.popular_categories || []
    }
  } catch (error) {
    console.error('加载工作台数据失败', error)
    ElMessage.error(error.message || '工作台数据加载失败，请检查网络或重新登录')
  } finally {
    loading.value = false
  }
}

const getStatusLabel = (status) => {
  const map = {
    pending: '待处理',
    approved: '已批准',
    rejected: '已驳回',
    completed: '已归还'
  }
  return map[status] || status
}

const getStatusTagType = (status) => {
  const map = {
    pending: 'warning',
    approved: 'success',
    rejected: 'danger',
    completed: 'info'
  }
  return map[status] || 'info'
}

const formatTime = (date) => dayjs(date).format('HH:mm')

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) currentUser.value = JSON.parse(userStr)
  fetchData()
  fetchApps()
  
  window.addEventListener('message-updated', handleMessageUpdated)
})

onUnmounted(() => {
  window.removeEventListener('message-updated', handleMessageUpdated)
})
</script>

